window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f82be07c388f71ea"]={"versions": [{"id": "FIG-f82be07c388f71ea", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-basiertes Prozessdiagramm) zur Spezifikation und Definition des System-Timings innerhalb des Gesamtsystementwurfs der AUTOSAR Classic Platform. Im Zentrum steht die methodische Aktivität „Define System Timing“ im Zusammenspiel mit vorgelagerten Artefakten aus System-Topologie, Software-Mapping und VFB-Timing.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Task Definition):</strong> <code>Define System Timing</code>\n</li><li><strong>Rolle:</strong> <code>System Engineer</code> (Kardinalität <code>1</code>, Stereotyp <code>«performs»</code>)\n</li><li><strong>Eingangsartefakte (<code>«input»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Communication Layers</code> (Kardinalität <code>1</code>)\n</li><li><code>Mapping of Software Components to Implementations</code> (Kardinalität <code>0..1</code>)\n</li><li><code>Mapping of Software Components to ECUs</code> (Kardinalität <code>1</code>)\n</li><li><code>Topology</code> (Kardinalität <code>1</code>)\n</li><li><code>Software Component Timing</code> (Kardinalität <code>0..1</code>)\n</li><li><code>VFB Timing</code> (Kardinalität <code>0..1</code>)\n</li></ul>\n</li><li><strong>Ausgangsartefakt (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li><code>System Timing</code> (Kardinalität <code>1</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>System Engineer</code> führt die Entwurfsaktivität <code>Define System Timing</code> aus. Als zwingend erforderliche Eingangsdaten müssen die System-<code>Topology</code> (1), das <code>Mapping of Software Components to ECUs</code> (1) sowie die Konfiguration der <code>Communication Layers</code> (1) vorliegen. Optional können detailliertere Timing-Beschreibungen herangezogen werden: <code>Software Component Timing</code> (0..1), <code>VFB Timing</code> (0..1) sowie das <code>Mapping of Software Components to Implementations</code> (0..1). Auf Basis dieser Eingaben erzeugt die Aktivität verbindlich das Artefakt <code>System Timing</code> (1) zur Beschreibung der zeitlichen Anforderungen und Garantien auf Systemebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert die Mindestvoraussetzungen für die Ableitung des System-Timings: Ohne Topologie, ECU-Mapping und Kommunikationsschichten kann kein konsistentes System-Timing erzeugt werden. Dagegen sind Implementierungs-Mapping und feingranulare SWC-/VFB-Timingmodelle optional und erlauben eine iterative bzw. inkrementelle Detaillierung der Timing-Spezifikation im AUTOSAR-Entwicklungsprozess.</p>"}, {"id": "FIG-26176c6164bf5a2d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-basiertes Prozessdiagramm) zur Spezifikation und Definition des System-Timings innerhalb des Gesamtsystementwurfs der AUTOSAR Classic Platform. Im Zentrum steht die methodische Aktivität „Define System Timing“ im Zusammenspiel mit vorgelagerten Artefakten aus System-Topologie, Software-Mapping und VFB-Timing.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Task Definition):</strong> <code>Define System Timing</code>\n</li><li><strong>Rolle:</strong> <code>System Engineer</code> (Kardinalität <code>1</code>, Stereotyp <code>«performs»</code>)\n</li><li><strong>Eingangsartefakte (<code>«input»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Communication Layers</code> (Kardinalität <code>1</code>)\n</li><li><code>Mapping of Software Components to Implementations</code> (Kardinalität <code>0..1</code>)\n</li><li><code>Mapping of Software Components to ECUs</code> (Kardinalität <code>1</code>)\n</li><li><code>Topology</code> (Kardinalität <code>1</code>)\n</li><li><code>Software Component Timing</code> (Kardinalität <code>0..1</code>)\n</li><li><code>VFB Timing</code> (Kardinalität <code>0..1</code>)\n</li></ul>\n</li><li><strong>Ausgangsartefakt (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li><code>System Timing</code> (Kardinalität <code>1</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>System Engineer</code> führt die Entwurfsaktivität <code>Define System Timing</code> aus. Als zwingend erforderliche Eingangsdaten müssen die System-<code>Topology</code> (1), das <code>Mapping of Software Components to ECUs</code> (1) sowie die Konfiguration der <code>Communication Layers</code> (1) vorliegen. Optional können detailliertere Timing-Beschreibungen herangezogen werden: <code>Software Component Timing</code> (0..1), <code>VFB Timing</code> (0..1) sowie das <code>Mapping of Software Components to Implementations</code> (0..1). Auf Basis dieser Eingaben erzeugt die Aktivität verbindlich das Artefakt <code>System Timing</code> (1) zur Beschreibung der zeitlichen Anforderungen und Garantien auf Systemebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert die Mindestvoraussetzungen für die Ableitung des System-Timings: Ohne Topologie, ECU-Mapping und Kommunikationsschichten kann kein konsistentes System-Timing erzeugt werden. Dagegen sind Implementierungs-Mapping und feingranulare SWC-/VFB-Timingmodelle optional und erlauben eine iterative bzw. inkrementelle Detaillierung der Timing-Spezifikation im AUTOSAR-Entwicklungsprozess.</p>"}], "trans": [{"from": "FIG-f82be07c388f71ea", "to": "FIG-26176c6164bf5a2d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
